import Testing
import Foundation
@testable import LibreMacAgentClient

// Cross-implementation fixtures: `Fixtures/*.cbor` are canonical FRAME BODY
// bytes (no 8-byte frame header) generated by LibreAgent's own C++ encoder —
// `tests/wire/MessagesRoundTripTest --dump-fixtures <dir>`, run against a
// real build of `LibreSCRS::Agent::Wire` — covering one instance of every
// reply/event shape, including the op-path shapes (OpProgress/OpResultReady/
// OpFinished) the card-free smoke tests cannot reach. Decoding every file
// here with THIS package's parser is the cross-implementation contract
// check: two independent encoders (Swift hand-written fixtures in
// MessagesRoundTripTests.swift; C++ QCBOR-backed encoder here) must agree
// byte-for-byte with one decoder.
//
// The REQUEST fixtures (client -> agent shapes) invert that: the C++ agent
// is the decoder there, so those tests byte-compare THIS package's
// `AgentRequest.encode(req: 1)` output against the C++ generator's bytes
// (the generator hardcodes req id 1) — both sides emit canonical CBOR, so
// equality is exact.
//
// To regenerate: LibreAgent build: `cmake --build <build-dir> -j4 --target
// MessagesRoundTripTest && <build-dir>/tests/wire/MessagesRoundTripTest
// --dump-fixtures <dir>`, then copy `<dir>/*.cbor` over this directory.

private func fixture(_ name: String) throws -> Data {
    let url = try #require(Bundle.module.url(forResource: name, withExtension: "cbor", subdirectory: "Fixtures"))
    return try Data(contentsOf: url)
}

private let sampleCertInfo = CertificateInfo(
    certId: "deadbeef",
    signingCapable: true,
    fields: ["Subject": ["CN": CertField(labelKey: "cn.subject.key", labelFallback: "Common Name", value: "John Doe")]],
    keyUsageBits: 1,
    ekus: ["clientAuth"],
    chainSubjectCns: ["Root CA"],
    trustStatus: 0)

@Suite("Cross-implementation fixtures (generated by the LibreAgent C++ encoder)")
struct CrossImplementationFixtureTests {

