    // ---- Unknown-reply-arm tolerance ----
    //
    // Layout.cbor / AppearanceFont.cbor are the `Manager1.LayoutVisualSignature`
    // / `GetAppearanceFont` reply arms — real, byte-exact new arms the C++ agent
    // now serves, generated by the SAME `--dump-fixtures` tool as every fixture
    // above. This Swift client has no layout API (the Qt client is the only
    // consumer for now) and `AgentMessages.decodeReply` was never taught
    // either arm's shape, so both must fall through its existing
    // no-known-key-matched path and throw `.unrecognizedShape` — never crash,
    // never hang, never silently mis-decode as some OTHER arm. This is the
    // forward-compatibility tolerance contract (a genuinely new agent
    // capability must not disturb an older client) exercised against a REAL
    // new wire arm for the first time, rather than a hand-rolled
    // malformed-frame stand-in. Both of `decodeReply`'s
    // two production callers swallow this via `try?` (`AgentClient.swift:337`,
    // `TokenAgentClient.swift:60`), so in practice the effect is "the pending
    // call times out on its own existing budget" — skip, not crash.
    @Test("Layout.cbor — a new reply arm this client build does not know decodes to unrecognizedShape, not a crash")
    func layoutArmDoesNotDisturbAnOlderClient() throws {
        let bytes = try fixture("Layout")
        #expect(throws: MessageError.unrecognizedShape) {
            try AgentMessages.decodeReply(bytes)
        }
    }

    @Test("AppearanceFont.cbor — ditto for the sibling fd-carrying new arm")
    func appearanceFontArmDoesNotDisturbAnOlderClient() throws {
        let bytes = try fixture("AppearanceFont")
        #expect(throws: MessageError.unrecognizedShape) {
            try AgentMessages.decodeReply(bytes)
        }
    }

    // Progressive per-group identity delivery ("OpIdentityGroup") is a genuinely
    // new EVENT `t` this client build has never heard of — the event-side twin
    // of the Layout/AppearanceFont reply-arm tolerance above, but through
    // `decodeEvent`'s OWN forward-compatibility path rather than `decodeReply`'s:
    // an unrecognized `t` there throws `.unknownMessage` (not `.unrecognizedShape`
    // — the two decoders use different sentinel errors for the same "shape I
    // don't know" situation; see `decodeEvent`'s own doc comment in
    // Messages.swift), which is skipped/ignored by every production event-dispatch
    // call site, never a crash or a dropped connection. Proves an OLD Swift
    // client build tolerates a NEWER agent that streams progressive groups.
    @Test("OpIdentityGroup.cbor — a new event this client build does not know is skipped, not a crash")
    func opIdentityGroupEventDoesNotDisturbAnOlderClient() throws {
        let bytes = try fixture("OpIdentityGroup")
        #expect(throws: MessageError.unknownMessage) {
            try AgentMessages.decodeEvent(bytes)
        }
    }

    // OpResultReadySignBatch.cbor exercises a DIFFERENT tolerance seam than
    // the three above: the outer event tag is "OpResultReady", a shape this
    // client already knows, but its nested `result.kind` is "SignBatch" — a
    // genuinely new op-result kind this client build has no case for (batch
    // signing has no Swift client API yet; that lands with the client-facing
    // surface in a later task). `parseOpResult`'s exhaustive `switch` on
    // `kind` already has a `default: throw .wrongType("kind")` branch
    // (Messages.swift), so an unrecognised nested kind is structurally
    // guaranteed to degrade to a clean typed error rather than crash or
    // mis-decode as some OTHER result — this is the SAME "skip, not crash"
    // guarantee as the reply-arm/event-tag cases above, proven here against
    // a real, byte-exact new result shape for the first time. Both of
    // `decodeEvent`'s production callers swallow this the same way they
    // swallow `.unknownMessage`/`.unrecognizedShape`.
    @Test("OpResultReadySignBatch.cbor — a new op-result kind this client build does not know decodes to wrongType, not a crash")
    func opResultReadySignBatchKindDoesNotDisturbAnOlderClient() throws {
        let bytes = try fixture("OpResultReadySignBatch")
        #expect(throws: MessageError.wrongType("kind")) {
            try AgentMessages.decodeEvent(bytes)
        }
    }

