    // ---- coverage guard: every fixture file gets a decode attempt above ----

    @Test("every checked-in fixture file is exercised by name above")
    func everyFixtureIsCovered() throws {
        let dir = try #require(Bundle.module.url(forResource: "Fixtures", withExtension: nil))
        let files = try FileManager.default.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil)
        let names = Set(files.map { $0.deletingPathExtension().lastPathComponent })
        let covered: Set<String> = [
            "HelloAck", "OpStarted", "State", "CertList", "CertDer", "Config", "Ack", "SignRecovery", "ErrCode",
            "ErrName", "ErrNameUnknownCredential", "ErrNameNoResult", "ReadTokenInfo", "ListCredentials", "ManagePin",
            "ActivateSigningKey",
            "ReaderAdded", "ReaderRemoved", "CardAdded", "CardRemoved", "PropertyChanged",
            "ConfigChanged", "OpProgress", "OpResultReadyIdentity", "OpResultReadyPhoto",
            "OpResultReadyCertificates", "OpResultReadySign", "OpResultReadyCredentialsList",
            "OpResultReadyCredentialsFailed", "OpFinished", "AgentQuiesced",
            // Unknown-arm/unknown-event/unknown-nested-kind tolerance
            // fixtures: each has its OWN dedicated test above (asserting the
            // specific decode error), not a decoded-value assertion like
            // every entry above, but still "exercised by name" — included
            // here so this guard's `names == covered` actually holds against
            // every checked-in file (found drifted — Layout/AppearanceFont
            // were never added here despite their own tests already
            // existing — and fixed in the SAME task that added the third
            // member of this family, OpIdentityGroup).
            "Layout", "AppearanceFont", "OpIdentityGroup",
            // OpResultReadySignBatch: the nested-kind tolerance twin of the
            // three above (see its own test's comment) — added in the SAME
            // task that introduced the "SignBatch" op-result kind.
            "OpResultReadySignBatch",
        ]
        #expect(names == covered)
    }
